import {uid,now,esc} from './core.js';
import {strictJSON} from './firmware-compare.js';
import {componentIdentity} from './components.js';
import {parseAdvisories,advisoryCandidates,validateAdvisoryProject,REVIEW_STATES} from './advisories.js';
export function createAdvisoryUI(ui){
 let filter='All',query='',visible=200;
 const scoped=()=>{const p=ui.project();return {p,components:p.components.filter(c=>c.deviceId===p.deviceId),advisories:(p.advisories||[]).filter(a=>a.deviceId===p.deviceId)};};
 const latest=(p,c,a)=>(p.advisoryReviews||[]).filter(r=>r.componentId===c&&r.advisoryId===a).at(-1);
 function view(){const {p,components,advisories}=scoped(),all=advisoryCandidates(components,advisories),rows=all.filter(r=>{const c=components.find(c=>c.id===r.componentId),a=advisories.find(a=>a.id===r.advisoryId);return (filter==='All'||(latest(p,r.componentId,r.advisoryId)?.status||'Unreviewed')===filter)&&[c.name,c.version,a.record.advisoryId,a.record.summary].join(' ').toLowerCase().includes(query.toLowerCase());});
 return `<section class="panel spaced"><div class="panel-head"><h2>Advisory review</h2>${ui.button('Import OSV JSON','advisory-import','small','upload')}</div><div class="panel-body"><p class="notice">Offline, dated records. Package matches are review candidates. Version ranges, build options, reachability and backported fixes require assessment. No automatic vulnerability verdict or online lookup.</p><div class="row between wrap spaced"><span>${advisories.length} records · ${all.length} candidates</span><label>Search <input id="advisory-query" value="${esc(query)}" placeholder="Component or advisory"></label>${ui.button('Apply search','advisory-search','small')}<label>Review status <select id="advisory-filter">${['All',...REVIEW_STATES].map(s=>`<option ${s===filter?'selected':''}>${s}</option>`).join('')}</select></label></div>${advisories.length?`<details class="spaced"><summary>Imported advisory records</summary>${advisories.map(a=>`<p class="spaced"><strong>${esc(a.record.advisoryId)}</strong> · modified ${esc(a.record.modified)}${a.record.withdrawn?' · WITHDRAWN':''}<br>${esc(a.record.summary)}<br>${ui.button('Original','evidence-detail','small','',`data-id="${a.evidenceId}"`)}</p>`).join('')}</details>`:''}<div class="table-wrap spaced"><table><thead><tr><th>Component</th><th>Advisory / basis</th><th>Review</th><th>Action</th></tr></thead><tbody>${rows.slice(0,visible).map(r=>{const c=components.find(c=>c.id===r.componentId),a=advisories.find(a=>a.id===r.advisoryId),review=latest(p,c.id,a.id);return `<tr><td>${esc(c.name)} ${esc(c.version)}<br><span class="smalltext">${esc(r.identity)}</span></td><td>${esc(a.record.advisoryId)}<br>${esc(r.basis)}<br><span class="smalltext">Modified ${esc(a.record.modified)}</span></td><td>${esc(review?.status||'Unreviewed')}${review?`<br><span class="smalltext">${esc(review.reviewer)} · ${esc(review.createdAt)}</span>`:''}</td><td>${ui.button('Review','advisory-review','small','',`data-id="${a.id}:${c.id}"`)}</td></tr>`;}).join('')||'<tr><td colspan="4">No candidates in this view. Import a component SBOM and dated OSV records; unmatched packages remain unassessed.</td></tr>'}</tbody></table></div>${rows.length>visible?ui.button('Show 200 more','advisory-more','small'):''}<p class="muted">${rows.length} candidates in this view.</p></div></section>`;
 }
 async function importFile(file){const p=ui.project(),deviceId=p.deviceId;if(file.size>1024*1024)throw Error('Use advisory JSON of 1 MiB or less.');const records=parseAdvisories(strictJSON(await file.text()));if((p.advisories||[]).length+records.length>100)throw Error('A project retains at most 100 advisory records.');const e=await ui.evidenceFromFile(file,'Advisory original','Imported OSV; dates describe the source, not currentness.',deviceId);if(ui.project()!==p||p.deviceId!==deviceId)throw Error('Project/device changed.');if((p.advisories||[]).some(a=>p.evidence.find(x=>x.id===a.evidenceId)?.hash===e.hash&&a.deviceId===deviceId))throw Error('This advisory original is already imported.');const additions=records.map(record=>({id:uid('adv'),deviceId,evidenceId:e.id,importedAt:now(),record}));validateAdvisoryProject({...p,evidence:[...p.evidence,e],advisories:[...(p.advisories||[]),...additions]});p.evidence.push(e);p.advisories??=[];p.advisories.push(...additions);ui.changed('Dated advisory originals preserved; candidates await review.');}
 function review(id){const [aid,cid]=id.split(':'),{p,components,advisories}=scoped(),a=advisories.find(a=>a.id===aid),c=components.find(c=>c.id===cid);if(!a||!c)throw Error('Advisory or component no longer exists.');const candidate=advisoryCandidates([c],[a])[0];if(!candidate)throw Error('Package no longer matches.');const prior=latest(p,cid,aid),history=(p.advisoryReviews||[]).filter(r=>r.componentId===cid&&r.advisoryId===aid),deviceId=p.deviceId;
 ui.showDialog('Review applicability',`<h3>${esc(a.record.advisoryId)} · ${esc(c.name)} ${esc(c.version)}</h3><p class="notice spaced">${esc(candidate.basis)}. This is an operator conclusion, not an automatic test. Affected, Not affected and Fixed require separate device assessment evidence.</p><p class="spaced">${esc(a.record.summary)}</p><p class="smalltext">Modified ${esc(a.record.modified)} · imported ${esc(a.importedAt)}${a.record.withdrawn?' · WITHDRAWN '+esc(a.record.withdrawn):''}</p><details class="spaced"><summary>Source details, ranges and references</summary><pre class="code-preview">${esc(a.record.details)}\n${esc(JSON.stringify(candidate.ranges,null,2))}</pre>${a.record.references.map(r=>`<p><a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.type||'Reference')} · ${esc(r.url)}</a></p>`).join('')}</details><div class="form-grid spaced">${ui.selectField('Applicability','status',REVIEW_STATES,prior?.status||'Unreviewed',true)}${ui.field('Reviewer','reviewer',prior?.reviewer||'','text',true)}${ui.area('Build, reachability, fix evidence and remaining uncertainty','notes',prior?.notes||'')}<div class="field full">Supporting assessment evidence${ui.evidenceChecks(prior?.evidenceIds||[])}</div></div>${history.length?`<details class="spaced"><summary>Review history · ${history.length}</summary>${history.map(r=>`<p><strong>${esc(r.status)}</strong> · ${esc(r.createdAt)} · ${esc(r.reviewer)}<br>${esc(r.notes)}</p>`).join('')}</details>`:''}`,data=>{if(ui.project()!==p||p.deviceId!==deviceId)throw Error('Project/device changed.');const r={id:uid('review'),deviceId,advisoryId:aid,componentId:cid,componentIdentity:componentIdentity(c).key,componentVersion:c.version||'',componentEvidenceId:c.evidenceId,status:data.get('status'),reviewer:data.get('reviewer'),notes:data.get('notes'),evidenceIds:data.getAll('evidenceIds'),createdAt:now()};validateAdvisoryProject({...p,advisoryReviews:[...(p.advisoryReviews||[]),r]});p.advisoryReviews??=[];p.advisoryReviews.push(r);ui.changed('Applicability review appended; earlier reviews retained.');},'Save review',prior?.status==='Affected'?ui.button('Create finding','advisory-finding','small','',`data-id="${aid}:${cid}"`):'');
 }
 function report(){const {p,components,advisories}=scoped();return `<h2>Advisory applicability review</h2><p>Imported advisory dates are retained. Matches are candidates; conclusions below are recorded by the reviewer, not automatically validated. ${advisories.length} advisory records imported.</p>${advisoryCandidates(components,advisories).map(x=>{const a=advisories.find(a=>a.id===x.advisoryId),c=components.find(c=>c.id===x.componentId),r=latest(p,c.id,a.id);return `<p><strong>${esc(a.record.advisoryId)} · ${esc(c.name)} ${esc(c.version)}</strong><br>Source modified ${esc(a.record.modified)}${a.record.withdrawn?' · WITHDRAWN':''} · ${esc(x.basis)}<br>Review: ${esc(r?.status||'Unreviewed')}${r?` · ${esc(r.reviewer)} · ${esc(r.createdAt)}<br>${esc(r.notes)}<br>Evidence: ${r.evidenceIds.map(esc).join(', ')}`:''}<br>Advisory original: ${esc(a.evidenceId)} · Component original: ${esc(c.evidenceId)}</p>`;}).join('')||'<p>No candidate matches recorded.</p>'}`;}
 return {view,report,wire(){const el=document.querySelector('#advisory-filter');if(el)el.onchange=e=>{filter=e.target.value;visible=200;ui.render();};},async action(name,id){if(!name.startsWith('advisory-'))return false;if(name==='advisory-search'){query=document.querySelector('#advisory-query').value;visible=200;ui.render();}else if(name==='advisory-more'){visible+=200;ui.render();}else if(name==='advisory-import')ui.pick('.json',importFile);else if(name==='advisory-review')review(id);else if(name==='advisory-finding'){const [a,c]=id.split(':'),p=ui.project(),r=latest(p,c,a),record=p.advisories.find(x=>x.id===a);if(r?.status!=='Affected')throw Error('Record affected applicability before creating a finding.');ui.findingDialog('',[...new Set([record.evidenceId,...r.evidenceIds])]);}return true;}};
}
